SELECT 'gongkao', '容斥问题', 'kp-xc-quantity-math-operation-inclusion-exclusion', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "容斥问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "容斥问题是数量关系高频考点，核心是多集合交并补的计数，两集合和三集合公式必须熟练掌握。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "两集合容斥公式：A∪B = A + B - A∩B，即总人数 = 只参加A + 只参加B + 都参加 + 都不参加"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "三集合容斥公式：A∪B∪C = A + B + C - A∩B - A∩C - B∩C + A∩B∩C"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "三集合标准型：总数 = A + B + C - 仅两项 - 2×三项都 + 都不参加"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "画韦恩图是解容斥题最直观的方法，用圆圈表示各集合，从内向外逐步填写"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "容斥问题常与最值结合，如\"至少参加一项\"求最小值，\"至多参加一项\"求最大值"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "公式法：直接套用两集合或三集合公式，适合条件清晰的题目"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "韦恩图法：画图标注各区域人数，从中心（三项都参加）向外填写"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "方程法：设未知量表示交集部分，列方程求解"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "整体减去都不：总数 - 都不参加 = 至少参加一项"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "混淆\"仅参加两项\"和\"参加两项\"：前者不含三项都参加的，后者可能包含"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "三集合公式中\"至少参加两项\"的计算容易漏掉三项都参加的部分"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记\"都不参加\"这一项，导致总数对不上"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "容斥问题每年必考1-2题，建议先背熟公式再做题，重点练习三集合标准型。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-容斥问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "容斥问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_inclusion_exclusion", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
